mapper.update:
update pickup_slot
start_time = #{startTime}, end_time = #{endTime}, capacity = #{capacity}, status = #{status}, version = version + 1, update_time = now()
where id = #{id}

mapper.select:
select * from pickup_slot

    and stall_id = #{stallId}
    and slot_date = #{slotDate}
    and status = #{status}

order by slot_date asc, start_time asc
